INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('0f443d88-e4a9-4e8f-a7e3-f37fd92aa370', '25', 'Гигиеник қоғоз маҳсулотлари, сульфитли ўрама қоғоз, фильтрлаш ва қадоқлашда ишлатиладиган қоғоз ва картон, ёғ ўтказмайдиган қоғоз ва пергамент, озиқ-овқат маҳсулотлари учун қоғоз идишлар ва патнислар, тухумларни қадоқлаш учун қутилар.', '4803 00, 4805 30, 4805 40 000 0, 4806, 4823 61 000 0, 4823 70 100 0', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('b5e6ec70-806d-43ab-b290-ea8afb5d261b', '26', 'Босма китоблар, рисолалар, варақалар ва шу каби босма материаллар, Болалар учун расмли китоблар, чизилган китоблар ёки рангли китоблар, газеталар, журналлар ва бошқа даврий нашрлар, тасвирланган ёки тасвирланмаган, ўз ичига олган ёки ўз ичига олмаган реклама материаллари.', '4901 10 000 0 — 4901 99 000 0, 4903 00 000 0, 4902 10 000 0 — 4902 90 000 0', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('050cb761-8422-4467-b145-302a6a50898a', '27', 'Ипак ипидан ёки ипак қолдиғидан газлама', '5007', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('f6f8c183-4a75-4f66-8170-685666ec178d', '28', 'Тароқ билан йигирилган ипак тўқимадан газламалар, ҳайвонларнинг ингичка ёки қалин толасидан тароқ билан йигирилган ипдан газламалар', '5111, 5112, 5113 00 000 0', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('30d35f92-1f20-4e55-a770-f5f7ae5968c4', '29', 'Зиғир толали газлама; жутдан олинган тола ёки 5303-товар позициясидаги бошқа пўстлоқ толалари; бошқа ўсимлик толалардан қилинган газлама; қоғоз йигирилган ипдан газламалар', '5309 — 5311', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('fb2fec8c-a01f-4bf1-b0a5-e23ad9dca841', '30', 'Синтетик комплекс ипдан газламалар, жумладан, 5404-товар позицияси материаллардан ишлаб чиқарилган газламалар; сунъий комплекс ипдан газламалар, шу жумладан, 5405 товар позицияси материаллардан ишлаб чиқарилган газламалар.', '5407 — 5408', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('0a6184df-7f39-4f3f-95a8-8d0309617c0a', '31', 'Оғирлиги 85% ёки ундан кўп ушбу толалардан ташкил топган синтетик толали газламалар; ушбу толаларнинг оғирлиги 85% дан кам бўлган синтетик толали газламалар, асосан ёки мустасно сифатида пахта толаси билан аралаштирилади, сирт зичлиги 170 g/m² дан ошмайди; ушбу толаларнинг оғирлиги 85% дан кам бўлган синтетик толали газламалар, асосан ёки мустасно сифатида пахта толаси билан аралаштирилган, сирт зичлиги 170 g/m² дан ортиқ; бошқа синтетик толали газламалар; сунъий толали газламалар', '5512 — 5516', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('a002cc00-6988-4b5d-a8fb-6d229fbf76c6', '32', 'Гигиеник мақсадларда ва тиббиётда фойдаланиш учун тўқимачилик материалларидан ва маҳсулотларидан тайёрланган пахта.', '5601 21-5601 22', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('ff5d922e-db89-478f-bf3f-3873e54d0237', '33', 'Йигирилган ёки йигирилмаган газлама бўлмаган материаллар, қопламали ёки қопламасиз, қайта ишланадиган ёки қайта ишланмайдиган.', '5603', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('d0b13a46-6598-4fb4-9779-2684b4b07620', '34', 'Тўқилган гиламлар ва бошқа тўқима пол қопламалари, тайёр ёки тайёр бўлмаган; гилам газлама ва бошқа полга тўшаладиган тўқима қопламалар, тафтингсиз ёки флокировкасиз, тайёр ёки тайёр бўлмаган, шу жумладан, «килим», «сумах», «кермани» ва қўлда тайёрланган ўхшаш гиламлар; гиламлар ва бошқа полга тўшаладиган тафтингли тўқима қопламалар, тайёр ёки тайёр бўлмаган; гиламлар ва бошқа полга тўшаладиган кигиз ёки фетрдан қилинган тўқима қопламалар, тафтингсиз ёки флокировкасиз, тайёр ёки тайёр бўлмаган; гиламлар ва бошқа полга тўшаладиган тўқима қопламалар, тайёр ёки тайёр бўлмаган', '5701 — 5705', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('4e11f2b6-46cf-4004-86f1-852fdea2778a', '35', 'Тукли газлама ва бахмал ипдан қилинган газлама; сочиқбоп пахмоқ газламалар ва ўхшаш пахмоқ газламалар, тафтинг қилинган тўқима материаллар; эшиб тўқилган газламалар; тюль ва бошқа тўрсимон мато, тўқилган матолар бундан мустасно; тўпдаги тўр, тасмалар ёки алоҳида орнаментлар турида; Бельгия, обьюссон, бовэ туридаги қўлда тўқилган гобеленлар ва ўхшаш гобеленлар ва гобеленлар, кашта игналари (мисол учун, ироқи, крест шаклидаги), тайёр ёки тайёр бўлмаган; ингичка тўқилмаган газламалар, бириктирилган елимлаб уланиш (болдюк); металл иплардан газламалар ва 5605 товар позициясидаги кийимларда ишлатиладиган металл билан ишлов берилган иплар, мебелбоп газлама сифатида ёки ўхшаш мақсадларда, бошқа жойда келтирилмаган ёки қўшилмаган; юмшоқ қатлам билан тикиш ёки бошқа усуллар орқали уланган бир неча тўқима материаллар қатламидан иборат бўлакдаги қавилган тўқима материаллар', '5801 — 5803, 5809 00 000 0, 5811 00 000 0', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('8b2aedbf-74c2-414b-a86a-08b1fc96a36c', '36', 'Пластмассага тўйинган, қопланган ёки бир-бирини такрорлайдиган тўқимачилик материаллари; резиналанган тўқимачилик материаллари', '5903, 5906', 'SERTIFIKAT', '502');
