INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('cba826f7-dfaf-46ec-a03e-2fee61e34233', '38', 'Машинада ёки қўлда тўқилган трикотаж тукли матолар, шу жумладан, узун тукли матолар ва пахмоқ матолар; эни 30 см дан кўп бўлмаган, 5% ёки ундан кўп эластик ёки резинали ипларни ўз ичига олган машинада ёки қўлда тўқилган трикотаж матолар; эни 30 см дан кўп бўлмаган, 5% ёки ундан кўп эластик ёки резинали ипларни ўз ичига олган машинада ёки қўлда тўқилган трикотаж матолар; асосда тўқилган матолар (шунингдек, галунларни тайёрлаш учун трикотаж машиналарида тўқилган); машинада ёки қўлда тўқилган бошқа трикотаж матолари', '6001, 6004 — 6006', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('e9ce091a-21e0-4334-b338-0a1f41b28639', '39', 'Эркаклар ёки ўғил болалар учун кўйлаклар машина ёки қўлда тўқилган трикотаж маҳсулотлардан; эркаклар ёки ўғил болалар учун кальсонлар, трусиклар, тунги кўйлак, пижамалар, чўмилишдан кейин кийиладиган халатлар, уйда кийиладиган халатлар ва ўхшаш маҳсулотлар, машина ёки қўлда тўқилган трикотаж маҳсулотлар; аёллар ёки қиз болалар учун комбинациялар, пастки юбкалар, трусиклар, панталонлар, тунги кўйлаклар, пижамалар, пеньюарлар, чўмилишдан кейин кийиладиган халатлар, уйда кийиладиган халатлар ва ўхшаш маҳсулотлар, машина ёки қўлда тўқилган трикотаж маҳсулотлардан; майкалар, енгли фуфайкалар ва бошқа ички фуфайкалар машина ёки қўлда тўқилган трикотаж маҳсулотлардан; болалар кийимлари ва болалар кийимларига керакли нарсалар, машина ёки қўлда тўқилган трикотаж маҳсулотлар; колоткалар, чулкилар, гольфилар ва подследниклар ва бошқалар, пайпоқ маҳсулотлари, тақсимланган босим билан компрессияли пайпоқ маҳсулотлари (масалан, веналарнинг варикоз кенгайишидан қийналаётганлар учун) ва тагликсиз оёқ-кийим, машина ёки қўлда тўқилган трикотаждан;', '6105 — 6109, 6111, 6115', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('0fd40375-e708-47ea-9aea-a1d946a49631', '40', 'Эркаклар ёки ўғил болалар учун кўйлаклар; аёллар ёки қиз болалар учун блузкалар, блузкалар ва блузонлар; эркаклар ёки ўғил болалар учун майкалар ва бошқа ички фуфайкалар, кальсонлар, трусиклар, тунги кўйлак,пижамалар, чўмилишдан кейин кийиладиган халатлар, уйда кийиладиган халатлар ва ўхшаш маҳсулотлар; аёллар ва қиз болалар учун майкалар ва бошқа ички фуфайкалар, комбинациялар, пастки юбкалар, трусиклар, панталонлар, тунги кўйлаклар, пижамалар, пеньюарлар, чўмилишдан кейин кийиладиган халатлар, уйда кийиладиган халатлар ва ўхшаш маҳсулотлар; болалар кийимлари ва болалар кийимларига керакли нарсалар; бюстгальтерлар, белбоғ, корсетлар, тортгичлар, боғичлар ва ўхшаш маҳсулотлар ва уларнинг машина ёки қўлда тўқилган трикотажёки нотрикотаж қисмлари;', '6205 — 6209, 6212', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('9d6cf5f3-abe4-49db-a60c-bb65494a057e', '41', 'Чойшаб, ётаржой, емакхона, ҳожатхона ва ошхона чойшаблари; ўт ўчирувчилар учун газламадан тайёрланган қутқарув пояслари', '6302, 6305, 6307 20 000 0', 'SERTIFIKAT', '502');
