INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('3de732ba-112e-4325-a259-6183e8ce8546', '45', 'Ғиштлар, блоклар, плиткалар ва шу каби оловга чидамли керамик маҳсулотлар; қўрилиш ғиштлари, қаватлар учун блоклар, Лаборатория, кимёвий ёки бошқа техник мақсадлар учун керамик буюмлар.', '6902, 6904, 6909', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('c54fe2eb-12c2-4fbc-8b39-5e10739d3d5d', '46', 'Автотранспорт воситалари учун хавфсиз шиша, озиқ-овқат маҳсулотлари ва дориларни қадоқлаш учун шиша идиш, емакхона ва ошхона идишлари, лаборатория, гигиеник ва фармацевтик вазифалар учун шиша идиш, ойналар', '7003 12 — 7003 30 000 0, 7004 20 — 7004 90, 7005 10 — 7005 30 000 0, 7006 00 100 0, 7006 00 900 0, 7007, 7008 00, 7009 91 000 0 , 7009 92 000 0, 7010, 7013, 7016 10 — 7016 90 700 9 , 7017, 7019', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('d4549f6b-9474-4c00-9029-4ef828d06988', '47', 'Кенглиги 600 мм дан кам ёки кўп бўлган темир ёки легирланмаган пўлатдан текис прокат, иссиқлайин ёйилган, совуқлайин ёйилган (совуқ ҳолда сиқилган), қопланган ёки қопланмаган, галваник ёки бошқа қоплама билан ёки у сиз; темир ёки легирланмаган пўлатдан эркин ўралган бухталардаги иссиқлайин ёйилган чивиқлар; Фақат болғалаш, иссиқ прокатлаш, иссиқлигича чўзиш ёки иссиқлигича экструдерлаш йўли билан ва кейинчалик ишлов беришсиз темир ёки легирланмаган пўлатдан чивиқлар; темир ёки легирланмаган пўлатдан бошқа чивиқлар; темир ёки легирланмаган пўлатдан бурчаклар, шаклдор ва махсус профиллар: швеллерлар, қўштаврлар ёки кенг токчали қўштаврлар, бурчак профиллари, таврли профиллар, бурчаклар, шаклдор ва махсус профиллар, с-, z-, омегасимон ёки туташтирилмаган профиллар, профилланган (қовурғали) листлар; темир ёки легирланмаган пўлатдан сим; қуймалар ёки бошқа бирламчи шаклдаги коррозияга барқарор пўлат; коррозияга барқарор пўлатдан ярим тайёр маҳсулотлар; кенглиги 600 мм дан кам ёки кўп бўлган коррозияга барқарор пўлатдан текис прокат; коррозияга барқарор пўлатдан бухталарга эркин ўралган, иссиқлайин ёйилган чивиқлар; коррозияга барқарор пўлатнинг бошқа турларидан чивиқлар; коррозияга барқарор пўлатдан бурчак, шаклдор ва махсус профиллар; коррозияга барқарор пўлатдан сим; қуймалар ёки бошқа бирламчи шаклдаги легирланган пўлатнинг бошқа турлари, легирланган пўлатнинг бошқа турларидан ярим тайёр маҳсулотлар; кенглиги 600 mm дан кам ёки кўп бўлган легирланган пўлатнинг бошқа турларидан текис прокат; легирланган пўлатнинг бошқа турларидан бухталарга эркин ўралган иссиқлайин ёйилган чивиқлар; легирланган пўлатнинг бошқа турларидан чивиқлар, бошқалар; легирланган пўлатнинг бошқа турларидан бурчак, шаклдор ва махсус профиллар; легирланган ёки легирланмаган пўлатдан бурғилаш ишлари учун кавак чивиқлар; легирланган пўлатнинг бошқа турларидан сим', '7208, 7209, 7210, 7211, 7212, 7213 — 7217, 7218, 7219, 7220, 7221, 7222, 7223, 7224, 7225, 7226, 7227, 7228, 7229', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('f3b288f1-62ea-43c0-b1a6-492242f5dbfa', '48', 'Қора металлардан шпунтланган конструкциялар, пармаланган ёки пармаланмаган,тешилган ёки тешилмаган, яхлит ёки йиғилган элементлардан ишлаб чиқарилган; қора металлардан пайвандланган бурчак, шаклдор ва махсус профиллар; газлар ва ёқилғилар учун қора металлардан резервуарлар, цистерналар, идишлар, газ плитаси, қуюқ ва суюқ ёқилғида иситиш печлари (фритюрницалар, манқаллар), овқатни тайёрлаш ва истеъмол қилиш учун емакхона ва ошхона идишлари, ноэлектрик қиздириш билан марказий иситиш учун радиаторлар ва қора металлар, уларнинг қисмлари, темир йўл ёки трамвай йўллари — рельслар, барча турдаги рельслар ва 1520 мм (янги) кенгликдаги излар учун стрелкали учликлар учун ишлатиладиган қора металлардан қисмлар, йиғилган стрелкали ўтказмалар; икки бошли рельсли накладкалар; алоҳида бириктириш тагликлари; костил бириктириш тагликлари; алоҳида темир йўл рельслари бирикмаларининг қисқичлари; темир йўл рельсларига пружинали рельс маҳкамлагичлар; йўлнинг эгилувчан пружинали элементлари (икки ўрамли шайбалар, тарелкасимон пружиналар, эгилувчан қисқичлар); рельсли бирикмалар учун қисқичли болтлар; рельсли бирикмалар учун қисқичли болтлар учун гайкалар; рельсли туташмалар учун туташ болтлар; рельсли туташмалар учун туташтириш болтлари учун гайкалар; рельсли бирикмалар учун ўрнатиш болтлари; рельсли бирикмалар учун ўрнатиш болтлари учун гайкалар; локомотив рессорлари', '7301, 7302, 7309 00 — 7310, 7311 00, 7318, 7320, 7321 (7321 90 000 0 дан ташқари), 7322, 7323 (7323 10 000 0 дан ташқари), 7324 10 000 0 (фуқаролик авиациясидан ташқари), 7324 21 000 0, 7324 29 000 0, 7324 90 000 0 (қисмларидан ташқари)', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('44438a03-8490-4e01-a991-2d81c526a23a', '49', 'Прокатка, штамповка кесиш усули билан легирланмаган пўлатдан тайёрланган, икки томонлама рух қопламали томбоп металл черепица (гофрланган) ва листли рух билан қопланган пўлат прокатдан тайёрланган томбоп элементлар (фурнитура, аксессуарлар, ясси прокатдан тайёрланган том учун бутловчи материаллар)', '7308 90 590 0', 'SERTIFIKAT', '502');
INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('180e8606-588c-4d2d-88b2-c3a29f63a4dc', '50', 'Изоляцияловчи тўлдирувчили гофрланган (қовурғасимон) листдан тайёрланган икки деворли панеллар ва деворбоп ва томбоп сэндвич-панеллар)', '7308 90 510 0', 'SERTIFIKAT', '502');
