INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('4fc2d9ba-6b73-4a21-b05e-dd5c5a143fa5', '54', 'Буғ қозонлари, марказий иситиш қозонлари, газгенераторлар ёки тозалаш қурилмалари билан ёки уларсиз сувли газ генераторлари; ацителенли газгенераторлари ва тозалаш ускуналари билан ёки уларсиз шунга ўхшаш газ генераторлари; куч қурилмалари, суюқлик ва ҳаво насослари, компрессорлар, ҳаво тортиш вентиляторлари ва шкафлари, ҳавони кондиционерлаш учун қурилмалар, ёқиш горелкалари, совитгичлар ва музлатгичлар, стерилизаторлар, дистилляторлар (электр ва электр бўлмаган иситиш билан саноат ёки лаборатория машиналари, ускуналари), марказга интилма қуритгичлар билан центрифугалар; суюқликлар ёки газларни филтрлаш ва тозалаш учун ускуналар ва қурилмалар, идиш-товоқ ювиш машиналари; бутилкалар ки бошқа сиғимларни ювиш ёки қуритиш учун ускуналар; бутилкалар, банкалар, яшикларни, қопларни ёки бошқа сиғимларни ёпиш, тўлдириш, тиқинлаш учун ускуналар, уларни тамғалаш ёки этикеткалаш учун; бутилкалар, банкалар, тубиклар ва шунга ўхшаш сиғимларни қалпоқлар ёки қопқоқлар билан зичлаб тиқинлаш учун ускуналар; қадоқлаш ёки тиқинлаш учун ускуналар (термик сиқиш йўли билан маҳсулотларни ўраш учун ишлатиладиган ускуналар); ичимликларни газлантириш учун ускуналар: (олдин фойдаланилган, кемалар ва фуқаролик авиациясида ишлатиладиганларидан ташқари), буғоқимли ёки қумоқимли ва шунга ўхшаш ускуналар: кўтариш талилари ва кўтаргичлар, турли хилдаги кўтариш кранлари, автоюклагичлар, юкларни кўчириш учун машиналар ва ускуналар, қишлоқ хўжалиги, чорвачилик ва овқат тайёрлаш учун қурилмалар ва аппаратлар, тўқувчилик станоклари, савдо автоматлари', '8402 11 000 — 8402 20000 9 8403 10, 8405 10 000 0, 8410 11 000 0, 8410 12 000 0, 8410 13 000 0, 8412 10 — 8412 80, 8413 11 000 0 — 8413 81 000 0 (8413 20 000 0, 8413 30 200 1, 8413 30 800 1 дан ташқари), 8414 10 — 8414 80 (8414 30 200 1, 8414 30 810 1, 8414 30 810 5, 8414 30 890 1, 8414 80 110 0, 8414 80 190 0 