INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('2981b942-0298-4951-be5e-d673ba29940a', '76', 'Йирик шохли қорамол (шунингдек, буйволлар) ёки отсимонлар оиласига кирувчи ҳайвонлар терисидан ошланган чарм ёки чарм красти, юнг қопламасисиз, қатланган ёки қатланмаган, лекин кейинги ишлов беришларсиз; қўй терилари ёки қўзичоқ териларидан олинган ошланган чарм ёки чарм красти, юнг қопламасисиз, қатланган ёки қатланмаган, лекин кейинги ишлов беришларсиз; бошқа ҳайвонлар терисидан олинган ошланган чарм ёки чарм краст, юнг ёки тук қопламасисиз, қатланган ёки қатланмаган, лекин кейинги ишлов беришларсиз; йирик шохли қорамол (шунингдек, буйволлар) ёки отсимонлар оиласига кирувчи ҳайвонлар териларидан ёки терининг қобиғи шаклида қўшимча равишда ишлов берилган теридан чарм красти, шу жумладан, пергамент остида ишлов берилган қорамол терисидан, юнг қопламасисиз, қатланган ёки қатланмаган; қўй терисидан ёки терининг қобиғи шаклида қўшимча равишда ишлов берилган чарм красти, шу жумладан, қўй терисидан ёки қўзиларнинг терисидан тайёрланган чарм, юнг қопламасисиз, қатланган ёки қатланмаган; теридан ёки терининг қобиғи шаклидаги қайта ишланган, шу жумладан, пергамент остида ишлов берилган бошқа ҳайвонларнинг терисидан чарм, юнг ёки тук қопламасисиз, қатланган ёки қатланмаган; замш (шунингдек, комбинацияланган замшлар); локли чарм ва ламинацияланган локли чарм; металлизация қилинган чарм; табиий чарм асосидаги композицион чарм ёки пластиналар, листлар ёки тасмалар, ёки ленталар, ўрамларда ёки ўрамларда бўлмаган чарм толалар', '4104 11 100 0 — 4114 20 000 0', 'DEKLARATSIYA', '502');
