INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('a8e083f8-ac21-4a40-8126-8cdfb7dde91e', '101', 'Ички ёниш двигателлари турбореактив гидротурбиналар, саноат ёки лаборатория печкалари ва камералари, маҳсулотларни тортиш учун ускуналар; суюқликлар ёки кукунларни супуриш, сепиш ёки сочиш учун механик қурилмалар (қўлда бошқариш ёки усиз); ўқланган ёки ўқланмаган ўт ўчиргичлар; пулверизаторлар ва шунга ўхшаш ускуналар; буғоқимли ёки қумоқимли ва шунга ўхшаш ускуналар: қишлоқ хўжалиги ва автойўл техникаси, Толали селлюлоза материалларидан бошқа маҳсулотлар ишлаб чиқариш ускуналари, нусха олиш-кўпайтириш машиналари, Кимёвий тўқимачилик материалларини экструдировка қилиш, тортиб олиш, текстура қилиш ёки кесиш учун машиналар, Тўқимачилик толаларини тайёрлаш машиналари, тўқув машиналари.', '8407 (8407 10 000, 8407 21, 8407 34 100 0, 8407 34 300, 8407 90 500 0 дан ташқари), 8417 10 000 0 — 8417 80 700 0, 8423 — 8424 89 000 9, 8432 10 000 0 — 8432 80 000 0, 8439 10 000 — 8439 30 000 0, 8443 31 — 8443 39 390 0 (8443 32 100 дан ташқари), 8444 00 — 8447 90 000 9', 'DEKLARATSIYA', '502');
