INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('a3d730fe-0ff4-4d18-8d6f-32014b4d6035', '54', 'Буғ қозонлари, марказий иситиш қозонлари, газгенераторлар ёки тозалаш қурилмалари билан ёки уларсиз сувли газ генераторлари, ацетиленли газгенераторлари ва тозалаш ускуналари билан ёки уларсиз шунга ўхшаш газ генераторлари, куч қурилмалари, суюқлик ва ҳаво насослари, компрессорлар, ҳаво тортиш вентиляторлари ва шкафлари, ҳавони кондиционерлаш учун қурилмалар, ёқиш горелкалари, совиткичлар ва музлаткичлар, маиший ҳаво музлаткичлар, маиший совиткичлар ва музлаткичлар (витринали совиткичлардан ташқари), стерилизаторлар, дистилляторлар (электр ёки электрсиз иситадиган саноат ёки лаборатория машина ва ускуналари), марказга интилма қуриткичлар билан центрифугалар, суюқликлар ёки газларни фильтрлаш ва тозалаш учун ускуналар ва қурилмалар, идиш-товоқ ювиш машиналари, бутилкалар ва бошқа сиғимларни ювиш ёки қуритиш учун ускуналар, бутилкалар, банкалар, яшикларни, қопларни ёки бошқа сиғимларни ёпиш, тўлдириш, тиқинлаш ва уларни тамғалаш ёки этикеткалаш учун ускуналар, бутилкалар, банкалар, тубиклар ва шунга ўхшаш сиғимларни қалпоқлар ёки қопқоқлар билан зичлаб тиқинлаш учун ускуналар, қадоқлаш ёки тиқинлаш учун ускуналар (термик сиқиш йўли билан маҳсулотларни ўраш учун ишлатиладиган ускуналар), ичимликларни газлантириш учун ускуналар, (олдин фойдаланилган, кемалар ва фуқаролик авиациясида ишлатиладиганларидан ташқари), буғоқимли ёки қумоқимли ва шунга ўхшаш ускуналар, кўтариш талилари ва кўтаркичлар, турли хилдаги кўтариш кранлари, автоюклагичлар, юкларни кўчириш учун машиналар ва ускуналар, қишлоқ хўжалиги, чорвачилик ва овқат тайёрлаш учун қурилмалар ва аппаратлар, тўқувчилик станоклари, савдо автоматлари, кранлар, клапанлар, вентиллар, трубопроводлар, қозонлар, резервуарлар, цистерналар, баклар босимни пасайтириш учун термостатик клапан ва арматуралар ёки шунга ўхшаш идишлар', '8402 11 000 — 8402 20 000 0, 8403 10, 8405 10 000 0,