INSERT INTO "TnVedRegulation" ("id", "item", "nameUz", "tnVedRaw", "category", "decision") VALUES ('55c6af45-a9bb-4d50-b54d-0c28f01c9fb8', '60', 'Оптик, прецизион, тиббиёт ёки жарроҳлик ва лаборатория асбоб-ускуналари ва аппаратлари (сарф ва назорат материалларининг эҳтиёт қисмларидан ташқари); ўлчаш ва назорат қилиш қурилмалари, баландликни ўлчагичлар ва спорт рулеткалари, автоматик тартибга солиш ва назорат қилиш учун ускуналар, геодезия ёки топографик (фотограмметриклар билан бирга), гидрографик, океонографик, гидрологик, метеорологик ёки геофизик, компаслардан ташқари қурилмалар ва асбоб-ускуналар; масофа ўлчагичлар, 0,05 г ёки ундан кўп сезувчанликдаги тарозилар, микрометрлар, кронциркуллар, штангенциркуллар ва калибрлар, нафас олиш аппаратураси ва ускуналари, асосий вазифаси рақамли нусха кўчириш бўлган, асл нусхасини сканерлаб ва нусхаларини электростатик усулда босиб чиқарувчи машиналар', '9008 50 000 0 (фақат слайдлар учун проекторлар), 9015 10 — 9015 80 990 0, 9016 00 100 0, 9017 30 000 0, 9017 80 100 0, 9018 — 9020 00 000 0 (9018 32 — 9018 49 9000 дан ташқари), 9022 (9022 90 000 0 дан ташқари), 9024 10 — 9024 80 900 0, 9025 11 — 9025 80 800 0, 9026 10 — 9026 80800 0, 9027 (9027 90 500 0, 9027 90 800 0 дан ташқари), 9028 10 000 0 — 9028 30 900 0, 9029 10 000 — 9029 20 900 0, 9030 10 000 0 — 9030 89 900 9, 9031 10 000 0 — 9031 80 980 0, 9032 10 — 9032 89 000', 'SERTIFIKAT', '43');
